package hu.bankmonitor.payments.transfers.checks;

/**
 * A condition a Transfer must satisfy before it can settle, answered by a party outside
 * this context.
 *
 * <p>A human approver and an automated service are the same kind of thing here: each
 * answers one of these constants for one Transfer, through the same operation. That
 * indistinguishability is what the asynchronous lifecycle was chosen for — a new condition
 * is a constant here and a line in {@link CheckPolicy}, not a new mechanism.
 *
 * <p>The constants are stored by name, so they are part of the schema: {@code
 * V4__check_ledger.sql} lists them in a check constraint, and renaming one is a migration
 * rather than a refactor.
 */
public enum Check {

	/** Automated fraud screening, answered by a service the outbox pushes the request to. */
	FRAUD,

	/** A person signing off in a back-office tool, reporting through the same endpoint. */
	MANUAL_APPROVAL
}
package hu.bankmonitor.payments.transfers.checks;

/**
 * A {@link Check}'s answer for one Transfer.
 *
 * <p>There are two answers and there is no third. A Check that has not answered has no
 * Verdict at all, which the ledger records as an absent column rather than as a constant
 * here — {@link CheckLedgerEntry} has the argument for that, and it is a claim about the
 * domain: "not yet answered" is the absence of an answer, not one of the answers.
 *
 * <p>The two are not symmetrical in what they cost. {@link #APPROVED} advances nothing on
 * its own — it is the other rows that decide — while {@link #REJECTED} ends the Transfer
 * whatever the rest of the ledger says. {@link LedgerDecision} is where that asymmetry is
 * written down.
 */
public enum Verdict {

	/** This Check is satisfied. The Transfer settles once every other Check agrees. */
	APPROVED,

	/** This Check says no, and that is the whole answer: the Transfer is rejected. */
	REJECTED
}
package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.transfers.checks.Check;
import hu.bankmonitor.payments.transfers.checks.Verdict;
import io.swagger.v3.oas.annotations.media.Schema;

/**
 * What a Check service is told once its Verdict has been recorded: the report it made, and
 * where the Transfer got to as a result.
 *
 * <p><b>{@code transferStatus} is the whole point of answering with a body at all.</b> A
 * Check service that reports one of two Checks learns its Verdict is not yet the last word;
 * one that reports the last learns that money moved. It is the same member
 * {@link TransferNotPendingException} puts on the wire when the report was too late, so
 * "where is this Transfer now" is answered in one vocabulary whether the report landed or
 * was refused.
 *
 * <p>The report is echoed back rather than assumed, because this endpoint is called by
 * machines with retries and logs: a receipt that named only a status would not say which of
 * several in-flight reports it was the receipt for.
 *
 * <p>Every member is listed as required for {@code TransferResponse}'s reason — springdoc
 * derives {@code required} from constraint annotations, and a response is never validated.
 */
@Schema(requiredProperties = {"transferId", "check", "verdict", "transferStatus"})
record VerdictReceipt(long transferId, Check check, Verdict verdict, TransferStatus transferStatus) {
}
package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.transfers.checks.Verdict;
import jakarta.validation.constraints.NotNull;

/**
 * What reporting a Verdict takes: the answer, and nothing else.
 *
 * <p>The Transfer and the Check are in the path rather than here, because together they
 * address the thing being reported on — the one outstanding row in one Transfer's Check
 * Ledger. Carrying either in the body as well would let a request name one Transfer in its
 * URL and another in its payload, and something would then have to decide which to believe;
 * {@code CreateTransferRequest} deletes the same class of bug by leaving the Currency out.
 *
 * <p>A record with one member rather than a bare {@link Verdict} on the wire, so that the
 * request has somewhere to grow: a reporting Check service with a reason, a correlation
 * identifier or the instant it decided adds a member here without changing the endpoint's
 * shape.
 */
record VerdictReport(@NotNull Verdict verdict) {
}

